package org.apache.commons.lang3.math;

import junit.framework.TestCase;

public class FractionBugOriginTest extends TestCase {

    public void testReducedFactory_int_int() {
        Fraction f = Fraction.getReducedFraction(Integer.MIN_VALUE, 2);
        assertEquals(Integer.MIN_VALUE / 2, f.getNumerator());
        assertEquals(1, f.getDenominator());
    }

    public void testReduce() {
        Fraction f = Fraction.getFraction(Integer.MIN_VALUE, 2);
        Fraction result = f.reduce();
        assertEquals(Integer.MIN_VALUE / 2, result.getNumerator());
        assertEquals(1, result.getDenominator());
    }
}

package org.apache.commons.lang3;

import junit.framework.TestCase;

public class StringEscapeUtilsBugOriginTest extends TestCase {
    public void testLang710() {
        try {
            String input = "&#03";
            String result = StringEscapeUtils.unescapeHtml4(input);
            // The reporter says it throws StringIndexOutOfBoundsException.
            // If it doesn't throw, we expect it to either leave it as is or unescape it,
            // but definitely not crash.
            assertEquals("&#03", result);
        } catch (StringIndexOutOfBoundsException e) {
            fail("Should not throw StringIndexOutOfBoundsException: " + e.getMessage());
        }
    }
}

package org.apache.commons.lang3;

import junit.framework.TestCase;

public class StringEscapeUtilsBugOriginTest extends TestCase {

    public void testEscapeXmlSupplementaryCharacters() {
        // A supplementary character: U+1D306 (TETRAGRAM FOR CENTRE)
        // In UTF-16, this is represented as \uD834\uDF06
        String supplementaryChar = "\uD834\uDF06";
        String escaped = StringEscapeUtils.escapeXml(supplementaryChar);

        // The bug is that it treats them as two separate characters.
        // Expected: "&#119558;" (decimal for 0x1D306)
        // Actual (buggy): "&#55348;&#57094;" (decimal for 0xD834 and 0xDF06)

        assertEquals("&#119558;", escaped);
    }
}

package org.apache.commons.lang3.time;

import java.util.Calendar;
import java.util.GregorianCalendar;
import java.util.TimeZone;
import junit.framework.TestCase;

public class DateUtilsBugOriginTest extends TestCase {

    public void testTruncatedCompareToWithDifferentTimeZones() {
        // The reporter states that comparing two calendars representing the same day/month
        // but in different timezones (one being America/Montevideo) fails to return 0
        // when truncated to MONTH.

        TimeZone montevideo = TimeZone.getTimeZone("America/Montevideo");
        TimeZone gmt = TimeZone.getTimeZone("GMT");

        // Nov 6, 2012
        GregorianCalendar c1 = new GregorianCalendar(2012, 10, 6);
        c1.setTimeZone(montevideo);

        GregorianCalendar c2 = new GregorianCalendar(2012, 10, 6);
        c2.setTimeZone(gmt);

        // The reporter expects the truncated comparison to return 0 for the same month
        // but it returned 1.
        int result = DateUtils.truncatedCompareTo(c1, c2, Calendar.MONTH);
        assertEquals("Truncated comparison for the same month in different timezones should be 0", 0, result);
    }
}

package org.apache.commons.lang3;

import junit.framework.TestCase;

public class StringEscapeUtilsBugOriginTest extends TestCase {
    public void testUnescapeJavaWithTrailingBackslash() {
        final String INVALID_ESCAPE = "\\";
        try {
            String result = StringEscapeUtils.unescapeJava(INVALID_ESCAPE);
            // The reporter expects an exception for an invalid escape sequence (trailing backslash).
            // Currently it returns "", which is considered incorrect by the reporter.
            // If it returns "", we fail the test to reproduce the "bug" (lack of exception).
            if ("".equals(result)) {
                fail("Expected an exception for invalid escape sequence '\\', but got an empty string.");
            }
        } catch (RuntimeException e) {
            // Expected behavior according to the reporter
        }
    }
}
